) AS (
  VALUES 
    (552::BIGINT, 'Ciertamente es una gran profesora, se nota que le gusta dar la materia e intenta siempre que usted se pueda sentir cómodo y seguro en las clases. Ahora sí, usted va a tener que poner un poco de su parte, principalmente con exámenes de años pasados, pero aún así ella califica bien y justo.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2026-07-12T00:00:00+00:00'::TIMESTAMPTZ, '762f51d4f6a58b33783c818b74a860ef4c067d0fbeada36daaa487b8bf4c9330'::TEXT, ARRAY[568]::BIGINT[]),
    (552::BIGINT, 'No enseña mucho de lo que sale en el examen. (y tampoco manda exámenes viejos para que uno practique). Si lleva con ella, esté dispuesto a hacer muchos quices, y tener en cuenta que va a tener que buscar exámenes viejos y practicar con ello. (Aunque ella si es de gran ayuda)'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes']::TEXT[], '2026-07-03T00:00:00+00:00'::TIMESTAMPTZ, 'e1709356c725353af1189e27dd88f8ddbc8cb7d8b1df441131631889ab7bf859'::TEXT, ARRAY[568]::BIGINT[]),
    (552::BIGINT, 'Muy buena profe, explica bien, volvería a llevar con ella. No es de regalar puntos, pero califica justo, da bastante material de apoyo muy bueno. Es atenta y responde rápido y claro a las dudas que uno tenga. Es super amable y comprensiva, demasiado humana.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2026-06-30T00:00:00+00:00'::TIMESTAMPTZ, '2a450165584eda3d436c7088404911cd236fff38e4823a03e34aab433fb64a63'::TEXT, ARRAY[568]::BIGINT[]),
    (552::BIGINT, 'La profe es un amor como persona, el semestre se pasa muy lindo con ella. Da muchísimo material de apoyo a lo largo del semestre. Explica súper bien los contenidos. Es bastante flexible con los quizes y siempre está dispuesta a ayudar. Califica justamente'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes']::TEXT[], '2026-06-26T00:00:00+00:00'::TIMESTAMPTZ, '62b638f93c083f444c28ac35e63b24aa2fbee60ef4c7cb25d9a22e17f9cde44c'::TEXT, ARRAY[568]::BIGINT[]),
    (552::BIGINT, 'Es buena profe, solo que en los tres exámenes del semestre entraron algunas cosas que no vimos en clase o lo evaluaban de una manera distinta a la vista en clase. Aparte de eso, da mucho material de apoyo y es un amor, llevaría Química II con ella (ojo porque no regala puntos si le hiciesen falta)'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2026-06-23T00:00:00+00:00'::TIMESTAMPTZ, '71b257a90761485d3e08e56912a471f218d0d3b310e26e9901016708ab3572af'::TEXT, ARRAY[568]::BIGINT[]),
    (552::BIGINT, 'Es la mejor profe de química, explica demasiado claro. Brinda mucho material de apoyo (videos, prácticas, juegos, etc.). Califica con mucho amor y muy suave. Siempre al inicio de la clase abre un espacio anónimo para escribir como nos sentimos. Como persona es bellísima y hace el semestre bonito'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-01-08T00:00:00+00:00'::TIMESTAMPTZ, '6ec5c2e7365547908c1a11348c752592645c4b3c940366757f1a4e3cc0b4e802'::TEXT, ARRAY[614]::BIGINT[]),
    (552::BIGINT, 'Es muy buena profe, el material que deja ayuda un montón, recomiendo mucho llevar con ella'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-12-17T00:00:00+00:00'::TIMESTAMPTZ, '9c98ee812e34ed928047a37f0d4017dc2de74c900ab74b10b01fc43ef771bbc0'::TEXT, ARRAY[614]::BIGINT[]),
    (552::BIGINT, 'Una de las mejores profes de quimica 2, brinda apoyo sus clases son entretenidas, se ven que conoce lo que enseña y la recomendaría 100 por ciento'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Brinda apoyo']::TEXT[], '2025-12-17T00:00:00+00:00'::TIMESTAMPTZ, '97c569cbcd1beff9469f04b7bf80b3a45adfd69bb3c163b8398a1ec2d6b92815'::TEXT, ARRAY[614]::BIGINT[]),
    (552::BIGINT, 'La mejor profe del mundo, explica super claro y deja material complementario para estudiar, hace muchos quices virtuales y en parejas, califica con mucho amor y de verdad hacer un ambiente muy lindo y comodo en el aula, se siente como profe de escuela. Si puede matricular hagalo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-12-04T00:00:00+00:00'::TIMESTAMPTZ, '39e2cbf7acd717e6d454a2f4d3e01ebb7a06a31c523bd885c525c90e13e99bf5'::TEXT, ARRAY[614]::BIGINT[]),
    (552::BIGINT, 'La mejor profe para llevar química explica muy bien y califica bonito. Además, hace gran parte de los quices virtuales.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'bccc007f12cc76801528ee5cc77117417d4577e2e83e26cc63d3b9d431de95b4'::TEXT, ARRAY[614]::BIGINT[]),
    (552::BIGINT, 'Excelente profesora y persona. La mejor opción para química II'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2025-07-24T00:00:00+00:00'::TIMESTAMPTZ, '60effc4e6b3870abf2ff7984fce13c7dad8edf1fc78e3d1b99a938393b966c4e'::TEXT, ARRAY[614]::BIGINT[]),
    (552::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-06-22T00:00:00+00:00'::TIMESTAMPTZ, '7b0157accdcf3e7be3e61da3c5b55ca77925d975e6a029abc524eb34557eeb79'::TEXT, ARRAY[614]::BIGINT[]),
    (552::BIGINT, 'Excelente tanto como profesora como ser humano, crea un ambiente muy bello en su clase, deja bastantes quizzes para la casa y en pareja, siempre al inicio hace un menti para comentar como hemos estado, en fin matricular con ella es lo mejor :)'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-11-30T00:00:00+00:00'::TIMESTAMPTZ, '58d242d1a2e1f92358cadf3ac792b84f9acb39b0141835099c5189f0e7b5950e'::TEXT, ARRAY[614]::BIGINT[]),
    (552::BIGINT, 'La profe es un amor, super humana incluso antes de iniciar la clase abre un menti para anonimamente decir cómo nos sentimos. La materia la explica tan bien que aunque no me interese la química su forma de explicar lo hace interesante. Matricule con ella 100% (pd: no da puntos si le hacen falta)'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-11-29T00:00:00+00:00'::TIMESTAMPTZ, '698019ddd77e3a7f8bed17b7de9482e8609175097fc422110e8d809d36664c89'::TEXT, ARRAY[614]::BIGINT[]),
    (552::BIGINT, 'Súper buena profe, es un amor de persona. Tanto como persona como profe es excelente se las recomiendo muchísimo. Si pueden matricular con ella no lo duden. Explica claro y puedes preguntar mil veces sin sentirte mal'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2024-11-25T00:00:00+00:00'::TIMESTAMPTZ, 'dd0865f3d3b8b5a49f228703a38221b747d812c74075f9ea26c24827e54034b8'::TEXT, ARRAY[614]::BIGINT[]),
    (552::BIGINT, 'Review a mitad de curso y oh mi dios que buena profe, no me interesa quimica mucho la verdad pero la profe hace que la clase se sienta como un lugar donde quieres estar, es profe UCR entonces se siente mucho mas humana que varios profes del TEC, pero si podes matricular con ella 10/10 hagalo'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2024-09-20T00:00:00+00:00'::TIMESTAMPTZ, 'c04d03cf84282c7b1c099cf0bce7852df85b3f0d7e9cccb0a3cd1dc70f1402df'::TEXT, ARRAY[614]::BIGINT[]),
    (552::BIGINT, 'La profe es super buena nota, explica de forma muy clara y lo vuelve a explicar las veces que se necesite. Vuelve la clase muy interesante, al menos para alguien como yo que no le gusta tanto química, me encantó como dió el curso. Además, hace muchos quices que ayudan mucho a subir la nota.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-19T00:00:00+00:00'::TIMESTAMPTZ, '24c1f9c154745f2a7526ef44066a20428c0b97bd66f3b867c9f8351a3305e7eb'::TEXT, ARRAY[614]::BIGINT[]),
    (552::BIGINT, 'Súper buena profe, realmente hace que el curso se disfrute bastante. Lo único es que sí hace quices un toque rudos, pero igual si la clase lo permite como al final de semestre ella hace quices extras para que se puedan reemplazar los que se tiene una mala nota'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-19T00:00:00+00:00'::TIMESTAMPTZ, '4237652c97d58d44b005e3d5addbe12317240c42ef80c120897615422f8a2900'::TEXT, ARRAY[614]::BIGINT[]),
    (552::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2024-06-12T00:00:00+00:00'::TIMESTAMPTZ, 'f9f9cba444e06804351c5a72fd784bf82a92f6cd7e11d58ba6198c715f6739c4'::TEXT, ARRAY[614]::BIGINT[]),
    (552::BIGINT, 'La profe es muy buena y explica demasiado bien, hace muchos quices y es un amor'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-12T00:00:00+00:00'::TIMESTAMPTZ, '65fc0e180de67de85e414a2e40deaa18650efcbfca9bcf6e82316100332213c1'::TEXT, ARRAY[568]::BIGINT[]),
    (552::BIGINT, 'Califica bien, las clases son livianas; atiende bien las dudas.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-12T00:00:00+00:00'::TIMESTAMPTZ, '38cfa207fe3337c7191617dc4695cbef2c538ca825afa5c4e9439b27009ff922'::TEXT, ARRAY[614]::BIGINT[]),
    (552::BIGINT, 'La profe Heilen es un amor con los estudiantes, muy amable y siempre dispuesta a ayudar. Además, tiene una facilidad para enseñar la materia que no lo he visto en ningún otro profesor. Definitivamente recomendada para personas que se les dificulta la materia, siempre busca ayudar.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-05-22T00:00:00+00:00'::TIMESTAMPTZ, 'adb92ac09320b31fc9acfd7b97be3f4c8f980a2e72ecbd3d038f8e35373ff0ee'::TEXT, ARRAY[614]::BIGINT[]),
    (552::BIGINT, 'Una eminencia, sabe un monton, explica super bien.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-01-23T00:00:00+00:00'::TIMESTAMPTZ, '68b033f50d8a410bb16ce66823b8d1c26cf307a2baef01f26607945be5534abe'::TEXT, ARRAY[568]::BIGINT[]),
    (552::BIGINT, 'Yo la recomendaría más para alguien que esté repitiendo el curso. Le encanta enseñar, se preocupa muchísimo por el bienestar de los estudiantes, siempre está dispuesta a repetir si lo necesita, los quices son un poco difíciles y las instrucciones a veces no son muy claras, pero en general es buena.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2023-11-05T00:00:00+00:00'::TIMESTAMPTZ, 'c4442d1fdc14a48a85b458b32ab8d9ca6a33774eb07eb13c40dc2b8840ceb4ce'::TEXT, ARRAY[568]::BIGINT[]),
    (552::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2023-07-25T00:00:00+00:00'::TIMESTAMPTZ, '24d5db5528e329ea91503ffd2f8070cba1f0be29a2d8d6bd94bcd65903ad1d30'::TEXT, ARRAY[568]::BIGINT[]),
    (552::BIGINT, 'Si tiene la oportunidad de matricular con esta profe NO LA DESAPROVECHE. De las mejores profes que pudieron llegar al tec, es sumamente buena persona, da clases de consulta sumamente buenos, es graciosa y los quiz son fáciles. Se nota el amor que tiene por dar clases.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-26T00:00:00+00:00'::TIMESTAMPTZ, '3d8a26758156dce35c18feb1a95182a23e3dc72c5a821a25c7c3b37bcca6001d'::TEXT, ARRAY[568]::BIGINT[]),
    (552::BIGINT, 'Review a mitad de curso: la profesora es excelente y tiene una personalidad super simpática. Sus clases son excelentes y hay muchísimo material de apoyo, como videos y prácticas. Llevaría de nuevo el curso con ella.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Clases excelentes']::TEXT[], '2023-03-17T00:00:00+00:00'::TIMESTAMPTZ, '3236cc29457f96d2da591985b961f7eb1ba874a1927de9bafd8b36e276980056'::TEXT, ARRAY[568]::BIGINT[]),
    (552::BIGINT, 'Profesora originalmente de la UCR. Su primer semestre en el Tec sería en el 2023. Según otros reviews de la UCR, explica muy bien las clases y es muy clara al hablar, pero los exámenes son difíciles según esos reviews.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Exámenes retadores']::TEXT[], '2023-02-08T00:00:00+00:00'::TIMESTAMPTZ, '6c2ad19b61ee37a5119a19c352d31e3ea33b410032306c15178a5f15e9b38338'::TEXT, ARRAY[568]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
